package com.novasoft.psicoapp.controller;
import com.novasoft.psicoapp.model.*; import com.novasoft.psicoapp.repo.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController{ private final UserRepo users; private final PasswordEncoder enc; public AdminController(UserRepo u,PasswordEncoder e){users=u;enc=e;} @GetMapping("/users") public List<User> users(){return users.findAll();} @PostMapping("/users") public User create(@RequestBody User u){u.password=enc.encode(u.password==null?"123456":u.password); return users.save(u);} @PutMapping("/users/{id}/role") public User role(@PathVariable Long id,@RequestBody Map<String,String> body){User u=users.findById(id).orElseThrow(); u.role=Role.valueOf(body.get("role")); return users.save(u);} @DeleteMapping("/users/{id}") public void delete(@PathVariable Long id){users.deleteById(id);} }
